head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 애니메이션 효과별 적용 (show / fadeIn / slideDown 클래스 추가)
//  - _2 : 아이템 리스트창이 위쪽으로 열리는 경우 slideDown 미적용 (direction=up / down 대조)
scwin.tData = {
    "description" : "[autoComplete > P > animation]<br/>AutoComplete 컴포넌트의 아이템 리스트창이 열릴때 적용될 애니메이션 효과를 설정합니다.",
    "validation" : [
        "slideDown 설정 시 direction=up 이면 'slideDown' 애니메이션 효과는 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_animation.setValue("slideDown");
    con_direction.setValue("up");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        animation : con_animation.getValue(),
        direction : con_direction.getValue()
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicAutoComplete(cList);
};



// 아이템 리스트창이 열린 방향과 리스트창 class 출력 (validation 1)
scwin.btn_getAnimation_onclick = function (e) {
    let itemTable = document.querySelector("[id='" + target1.id + "_itemTable']");

    if (itemTable === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("아이템 리스트창을 한번 열어야 리스트창 정보를 확인할 수 있음");
        return;
    }

    // 리스트창 top 이 컴포넌트 top 보다 위면 위쪽으로 열린 것
    let compTop = WebSquare.style.getAbsoluteTop(target1.render);
    let strDirection = (parseFloat(itemTable.style.top) < compTop) ? "위쪽" : "아래쪽";

    wf_body_bottom.getObj("scwin").setReturnValue("animation : " + target1.options.animation + " / direction : " + target1.options.direction + " -> 리스트창 열린 방향 : " + strDirection + " / className : " + itemTable.className);
};
